<?php function statCard($title,$value,$icon,$tone,$change){ ?><article class="stat-card"><div class="stat-head"><span><?=$title?></span><span class="stat-icon <?=$tone?>"><?=iconSvg($icon,'stat-svg')?></span></div><strong class="stat-value"><?=$value?></strong><div class="stat-foot"><span class="positive"><?=iconSvg('activity','activity-svg')?> <?=$change?></span><span>vs. mês anterior</span></div></article><?php } ?>